import ast,base64,hashlib,json,os,pathlib,pty,select,secrets,time
os.umask(0o077)
root=pathlib.Path('/workspace');state=root/'.aj-diagnostics';state.mkdir(mode=0o700,parents=True,exist_ok=True)
path=pathlib.Path('/opt/aj/ziomalskit/h3/docker/instance.py')
expected='fd7cf5ad8a73c0947a01a807b06c2f4811817702a27994e6195e223f25434fa2'
payload=base64.b64decode('')
target_hash=hashlib.sha256(payload).hexdigest()
current=path.read_bytes();current_hash=hashlib.sha256(current).hexdigest()
assert current_hash in (expected,'c3401839a24a03167440d6b225751d1f369105a7c4c6439308a6885170a9bdfe',target_hash),'Unexpected image source; refusing runtime patch'
ast.parse(payload)
if current_hash!=target_hash:
 backup=state/'instance-before-cgroup-v1.py'
 if backup.exists():assert hashlib.sha256(backup.read_bytes()).hexdigest()==expected
 else:backup.write_bytes(current)
 temp=path.with_suffix('.py.tmp');temp.write_bytes(payload);os.chmod(temp,path.stat().st_mode & 0o777);temp.replace(path)
(state/'cgroup-v1-hotfix.json').write_text(json.dumps({'base_sha256':expected,'patched_sha256':target_hash},indent=2))
print('Cgroup v1 patch installed with exact source checksum',flush=True)
password=None
pid,fd=pty.fork()
if pid==0:os.execvp('aj-docker',['aj-docker','init'])
pending=b'';recent=b'';sent=False;status=None
with (state/'init.log').open('ab',buffering=0) as log:
 while True:
  readable,_,_=select.select([fd],[],[],1)
  if readable:
   try:chunk=os.read(fd,65536)
   except OSError:break
   if not chunk:break
   log.write(chunk);recent=(recent+chunk)[-4096:]
   if b'Choose private panel password' in recent and not sent:
    password=secrets.token_urlsafe(36)
    private=pathlib.Path('/root/.aj-panel-password');private.write_text(password+'\n');os.chmod(private,0o600)
    os.write(fd,(password+'\n').encode());sent=True
   pending+=chunk
   while b'\n' in pending:
    raw,pending=pending.split(b'\n',1);line=raw.decode('utf-8','replace').replace('\r','')
    if password:line=line.replace(password,'[REDACTED]')
    if line.startswith('{'):
     try:
      obj=json.loads(line)
      if 'available_ram_bytes' in obj:print(json.dumps({k:obj[k] for k in ['available_ram_bytes','effective_cpus']}),flush=True)
      elif 'disk' in obj:print(json.dumps({'disk':obj['disk'],'reserve_bytes':obj['reserve_bytes']}),flush=True)
     except ValueError:pass
    elif any(term in line for term in ['Runtime health','AJ Docker blocked','PASS','FAIL','Error','Traceback','SageAttention','sageattention','CUDA','pidfd','dependency','Missing','verified','No weights downloaded']):
     print(line[:3000],flush=True)
  done,code=os.waitpid(pid,os.WNOHANG)
  if done:status=code;break
 if status is None:_,status=os.waitpid(pid,0)
os.close(fd)
result=os.waitstatus_to_exitcode(status)
print('AJ_INIT_EXIT='+str(result),flush=True)
transfer=state/'models-transfer.json'
if transfer.exists():print('MODEL_TRANSFER_STATUS '+transfer.read_text(),flush=True)
raise SystemExit(result)
